const btnCloseProducts=document.querySelectorAll(".btn-close-products"),btnCardsProducts=document.querySelectorAll(".card__button--btn"),modalProducts=document.querySelector(".main__container__filter");function appearsAndDisappearsModalProducts(){modalProducts.style.display="none";for(let t=0;t<btnCardsProducts.length;t++)btnCardsProducts[t].addEventListener("click",function(){modalProducts.style.display="flex"});for(let t=0;t<btnCloseProducts.length;t++)btnCloseProducts[t].addEventListener("click",function(){modalProducts.style.display="none"})}function displayProductsModal(t){t.getAttribute("data-id");var e=t.getAttribute("data-nom"),o=t.getAttribute("data-sousTitre"),r=t.getAttribute("data-prix"),d=t.getAttribute("data-stock"),a=t.getAttribute("data-description"),n=t.getAttribute("data-image");document.querySelector("#dataTitleModal").innerHTML=e,document.querySelector("#dataSubtitleModal").innerHTML=o,document.querySelector("#dataDescriptionModal").innerHTML=a,document.querySelector("#dataPriceModal").innerText="Prix : "+r+" €",document.querySelector("#dataStockModal").innerText="Stock : "+d,document.querySelector("#datePictureModal").src="/public/assets/images/produits/"+n}var boutons=document.querySelectorAll(".card__button--btn");boutons.forEach(function(t){t.addEventListener("click",function(){displayProductsModal(t)})}),appearsAndDisappearsModalProducts();